import{_ as o,a as r,b as a,c as d}from"./chunks/compare-toolbar.C0Xi3fiu.js";import{_ as e,o as i,c as s,a2 as l}from"./chunks/framework.Dx-TCpNt.js";const q=JSON.parse('{"title":"比較リーダー","description":"比較リーダーは、2つ以上の言語の同じコマを並べて、または重ねて表示し、比較が正確になるように絵を位置合わせできる機能です。","frontmatter":{"description":"比較リーダーは、2つ以上の言語の同じコマを並べて、または重ねて表示し、比較が正確になるように絵を位置合わせできる機能です。"},"headers":[],"relativePath":"ja/guide/compare.md","filePath":"ja/guide/compare.md","lastUpdated":1794830541000}'),n={name:"ja/guide/compare.md"};function g(c,t,h,u,p,b){return i(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="比較リーダー" tabindex="-1">比較リーダー <a class="header-anchor" href="#比較リーダー" aria-label="Permalink to &quot;比較リーダー&quot;">​</a></h1><p>比較リーダーは、2つ以上の言語の同じコマを並べて、または重ねて表示し、比較が正確になるように絵を位置合わせできる機能です。</p><figure class="shot"><img src="'+o+'" alt="同じページを日本語・中国語・英語で並べて表示した比較リーダー"><figcaption>3言語の並列モード。言語ごとに独立したペインで、位置合わせはページごとに保存され、エクスポートにも適用されます。</figcaption></figure><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>同じ本の2つの版が正確に同じ形状を持つことはほとんどありません。生肉と翻訳版では位置、切り取り、倍率が違います。ページ全体を比較すると、小さな違いは隠れてしまいます。<strong>コマを1つずつ</strong>、言語ごとに独立して位置合わせしながら比較すると、言い回し、語気、省略が見えてきます。</p><h2 id="レイアウト" tabindex="-1">レイアウト <a class="header-anchor" href="#レイアウト" aria-label="Permalink to &quot;レイアウト&quot;">​</a></h2><table tabindex="0"><thead><tr><th>コントロール</th><th>動作</th></tr></thead><tbody><tr><td><strong>言語チップ</strong>（<code>JA</code>、<code>ZH</code>、<code>EN</code> など）</td><td>言語をオン / オフにします。このページにない言語は、ツールチップ付きで無効になります。</td></tr><tr><td>チップをドラッグ</td><td>ペインの順序を変更します。順序は記憶されます。</td></tr><tr><td><code>↺</code></td><td>ライブラリの言語順に戻します。</td></tr><tr><td><strong>並列</strong></td><td>選択した言語ごとに1列。狭いウィンドウではペインが縦に積み重なります。</td></tr><tr><td><strong>重ね表示</strong></td><td>選択したすべての言語を同じ枠に描画します。</td></tr><tr><td><strong>乗算</strong>（重ね表示のみ）</td><td>レイヤーを乗算し、線画が透けて見えるようにします。</td></tr><tr><td><strong>位置合わせ対象</strong> チップ（重ね表示のみ）</td><td>ドラッグする言語を選び、2つのペインが同時に動かないようにします。</td></tr></tbody></table><h2 id="マスク" tabindex="-1">マスク <a class="header-anchor" href="#マスク" aria-label="Permalink to &quot;マスク&quot;">​</a></h2><p>マスクは、自分の理解度を試す間、その言語の画像を隠します——答えを隠して自分の実力を測る、あれと同じです。</p><table tabindex="0"><thead><tr><th>コントロール</th><th>動作</th></tr></thead><tbody><tr><td><strong>マスク：オン / オフ</strong></td><td>全体の切り替え。<code>H</code> で切り替え、<code>Shift+H</code> ですべて表示します。</td></tr><tr><td>言語ごとの <code>◐</code> / <code>◯</code> チップ</td><td>マスクする言語を選びます。</td></tr><tr><td><strong>マスク表示</strong></td><td><strong>ぼかし</strong> または <strong>塗りつぶし</strong>。</td></tr><tr><td><strong>全マスク</strong></td><td>現在表示中のすべてのペインをマスクします。</td></tr><tr><td><strong>全表示</strong></td><td>全体の切り替えをオフにします。</td></tr><tr><td><strong>既定…</strong></td><td>セッションをまたいで、最初からマスクする言語を記憶します。</td></tr><tr><td>マスク中のペインをクリック</td><td>一時的に表示します。もう一度絵をクリックするとマスクに戻ります。</td></tr></tbody></table><p>マスクは<strong>読むときの好み</strong>にすぎません。HTML と PNG のエクスポートにマスクは含まれません。マスクの既定値はページ JSON ではなくブラウザに保存されます。</p><figure class="shot"><img src="'+r+'" alt="中国語と英語をぼかしでマスクした比較リーダー。マスク表示の選択と既定マスクのチェックボックス"><figcaption>中国語と英語をマスクした状態。既定マスクは、最初から隠す言語を記憶します。マスクされたペインをクリックすると一時的に表示できます。</figcaption></figure><h2 id="ズーム、パン、範囲" tabindex="-1">ズーム、パン、範囲 <a class="header-anchor" href="#ズーム、パン、範囲" aria-label="Permalink to &quot;ズーム、パン、範囲&quot;">​</a></h2><ul><li>ペイン上での<strong>ホイール</strong>はその言語を拡大縮小します。ホイールはポインターがペイン内にある間だけ捕捉されるため、それ以外の場所では通常のページスクロールが使えます。</li><li>ペインを<strong>ドラッグ</strong>するとパンします。</li><li><strong>ドラッグ/拡大縮小</strong> の範囲には <strong>ページ全体</strong> と <strong>このコマ</strong> の2つのモードがあります。</li><li>既定の範囲にかかわらず、ドラッグやスクロール中に <code>Alt</code> を押すと現在のコマだけを調整できます。</li><li><strong>前のコマ / 次のコマ</strong> は読む順にフォーカス中のコマを移動します。ページの先頭のコマでさらに前へ、末尾のコマでさらに次へ進むと、隣のページへ移ってそのページの最後／最初のコマにフォーカスします。前処理で除外したページは飛ばし、話の境界もまたぎます。巻の最初／最後では移動しません。未保存の変更がある場合は、通常どおり保存モードの確認が先に入ります。</li><li><strong>すべてリセット</strong> は現在の範囲のオフセットを消去します。</li></ul><p>各言語は <code>{ x, y, scale }</code> を持ちます。<code>x</code> と <code>y</code> はコマの幅と高さに対する比率で、<code>scale</code> は切り取り範囲を0.5倍から3倍に拡大縮小します。</p><h2 id="位置合わせモード" tabindex="-1">位置合わせモード <a class="header-anchor" href="#位置合わせモード" aria-label="Permalink to &quot;位置合わせモード&quot;">​</a></h2><p>位置合わせはページ JSON に保存され、画像に焼き込まれることはありません。</p><table tabindex="0"><thead><tr><th>モード</th><th>動作</th><th>向いている場面</th></tr></thead><tbody><tr><td><strong>ページ全体のオフセット</strong></td><td>どのコマをドラッグしても、その言語のページ全体が平行移動します。</td><td>スキャン全体が同じ量だけずれている場合。</td></tr><tr><td><strong>コマごとのオフセット</strong></td><td>コマごとに個別のオフセットを持ちます。</td><td>電子版と紙版でコマの位置が違う場合。</td></tr><tr><td><strong>アンカー合わせ</strong></td><td>基準言語の特徴点をクリックし、別の言語の同じ点をクリックすると、オフセットが計算されます。</td><td>1つの細部を正確に、再現性をもって位置合わせする場合。</td></tr><tr><td><strong>グリッド吸着</strong></td><td>ドラッグ時に0.5%、1%、2%、5%のステップに吸着します。</td><td>数値が整い、再現できるオフセットが必要な場合。</td></tr></tbody></table><p>アンカーモードでは、基準言語を示すプロンプトが表示されます。まず任意のセルで特徴点をクリックし、次に別のセルで同じ位置をクリックします。<strong>基準点をキャンセル</strong> は保留中の点を消去します。保留中のアンカーは保存されません。</p><h3 id="位置合わせ設定" tabindex="-1">位置合わせ設定 <a class="header-anchor" href="#位置合わせ設定" aria-label="Permalink to &quot;位置合わせ設定&quot;">​</a></h3><p><strong>位置合わせ設定</strong> を開くと、次のパネルが表示されます。</p><ul><li><strong>対象</strong> の言語チップ。</li><li>選択した対象の正確な <strong>X</strong>、<strong>Y</strong>、<strong>拡大率</strong> 入力。</li><li><strong>このページの全コマをリセット</strong> — コマごとのオフセットを消去します。ページ全体のオフセットは影響を受けません。</li><li><strong>現在のコマをリセット</strong> — 選択中のコマのコマごとのオフセットだけを消去します。</li><li><strong>ページプリセットとして保存</strong> / <strong>話プリセットとして保存</strong> — 現在の位置合わせを <code>data/presets/align.json</code> に保存します。</li><li>プリセットを選択して <strong>このページに適用</strong> または <strong>話全体に適用</strong>。<strong>削除</strong> で削除します。</li></ul><p>プリセットには位置合わせモード、オフセット、コマごとのオフセット、グリッドのステップが記録されます。話プリセットを適用するのが、話全体にわたって一様にずれたスキャンを修正する最速の方法です。</p><figure class="shot"><img src="'+a+'" alt="位置合わせ設定。対象言語、X、Y、拡大率の入力、リセットボタン、プリセット"><figcaption>位置合わせ設定。対象言語を選び、数値を直接入力するか、現在の位置合わせをページ / 話プリセットとして保存できます。</figcaption></figure><h2 id="比較リーダーでの注釈" tabindex="-1">比較リーダーでの注釈 <a class="header-anchor" href="#比較リーダーでの注釈" aria-label="Permalink to &quot;比較リーダーでの注釈&quot;">​</a></h2><p>注釈ツールバーはここでも使えます。生肉と翻訳版の言い回しの違いを印すのに、一番速い場所です。</p><ul><li>新しい注釈はワークベンチと同じ適用範囲に従います。コマを選んでいれば、次の注釈はそのコマの中に入ります。</li><li>比較表示では注釈レイヤーが既定で表示されるので、見比べながら印を付けられます。<strong>注釈</strong> スイッチで隠せます。</li><li>注釈は表示をまたいで共有されます。比較リーダーで付けた印は、コマ分割ワークベンチにもエクスポートにも出ます。</li><li><code>Esc</code> で現在のツールを終了し、<code>Delete</code> で選択中の注釈を削除します。</li><li>注釈を選択すると、ツールバーの<strong>アンカー</strong>が位置指定モードになります。クリックで点を置くか、小さな枠をドラッグして範囲を囲みます。<strong>アンカーを解除</strong> で位置指定を消します。</li><li><strong>引き出し線</strong> は既定でオンで、注釈からアンカーへ線を引きます。テキストとバッジはアンカーが無くても所属コマにつながるため、古い注釈でも自然に表示されます。オフにすると注釈だけが残ります。</li><li>アンカーはページ座標で保存されるため、パン・ズーム・言語切り替えでも絵に追従します。PNG、HTML、Word（注釈の焼き込み）の3つの書き出しすべてで、エディターと同じアンカーマーカーと引き出し線が描かれます。</li></ul><h2 id="実用的な比較の流れ" tabindex="-1">実用的な比較の流れ <a class="header-anchor" href="#実用的な比較の流れ" aria-label="Permalink to &quot;実用的な比較の流れ&quot;">​</a></h2><ol><li><strong>比較読み</strong>（<code>C</code>）でページを開きます。</li><li><code>JA</code> + <code>ZH</code>（あれば <code>EN</code> も）を、読みたい順に有効にします。</li><li>版によってコマごとに違いがあるなら <strong>コマごとのオフセット</strong> を選び、そうでなければ <strong>ページ全体のオフセット</strong> から始めます。</li><li>コマの内容がそろうまで、各言語のペインをドラッグします。</li><li>話の残りも同じオフセットなら、位置合わせプリセットを保存します。</li><li><strong>乗算</strong> 付きの <strong>重ね表示</strong> に切り替え、線画や文字の違いを探します。</li><li>マスクをオンにして自分を試し、その後ペインを順に表示します。</li></ol><h2 id="動作の詳細" tabindex="-1">動作の詳細 <a class="header-anchor" href="#動作の詳細" aria-label="Permalink to &quot;動作の詳細&quot;">​</a></h2><ul><li>位置合わせのオフセットはエクスポート時にも適用されるため、書き出した切り取り範囲は見た目と一致します。</li><li>リーダーにはまずコマが必要です。コマがないページでは、コマ分割ワークベンチへ行くようヒントが表示されます。</li><li>ページを切り替えると、マスクの設定は保持されますが、一時的な表示は解除されます。</li><li>各ペインにはノート件数が表示されます。ここでコマを選ぶと、共有のノート列で新しいノートがそのコマに紐付きます。</li><li>画像のない言語は、空のペインではなくプレースホルダーを表示します。</li></ul><figure class="shot"><img src="'+d+'" alt="比較ツールバー。言語チップ、マスク、並列と重ね表示、位置合わせの範囲、コマ単位のドラッグ切り替え"><figcaption>比較ツールバー。言語チップ、マスク、並列 / 重ね表示、位置合わせの範囲、コマ単位のドラッグ切り替え。</figcaption></figure><h2 id="コマ詳細ビュー" tabindex="-1">コマ詳細ビュー <a class="header-anchor" href="#コマ詳細ビュー" aria-label="Permalink to &quot;コマ詳細ビュー&quot;">​</a></h2><p>コマの行をダブルクリックすると、そのコマが拡大表示されます。行全体が対象です。言語ペイン、コマ番号のある見出し、切り取り範囲の外側の余白も、同じコマを開きます。エディター、ドラッグハンドル、ボタン、リンクの内側のクリックは除外され、タッチ環境では行のダブルタップが同じ働きをします。</p><ul><li><strong>言語ごとの位置合わせ</strong> — 位置合わせドロワーには、言語ごとの <code>Δx</code> / <code>Δy</code> 表示、1% 刻みの矢印ナッジ、ズーム − / +、その列のリセットがあります。</li><li><strong>すべての言語</strong> — 同じ矢印パッドがすべての列をまとめて動かし、<strong>すべてリセット</strong> で一度に戻せます。</li><li>この詳細ビューでの調整は現在のセッションだけ有効で、ページや保存済みの位置合わせには書き戻しません。</li><li>ペインの下のノート列はこのコマに直接書き込みます。コマを切り替える、ページをめくる、戻るときは、先に下書きを保存します。</li></ul><h2 id="原版ビュー" tabindex="-1">原版ビュー <a class="header-anchor" href="#原版ビュー" aria-label="Permalink to &quot;原版ビュー&quot;">​</a></h2><p><strong>原版</strong>（<code>O</code>）は、利用できる言語ごとに未裁切のページ全体を横に並べ、0.5×〜6× のホイールズーム、ドラッグでのパン、同じ言語別マスクを提供します。検出したコマの外側を確認するためのビューです。</p><ul><li><strong>連動 / 独立</strong> — 原版ビューのツールバーにある切り替えで、パンとズームを共有するかを決めます。<strong>連動</strong>では、どれか 1 列をドラッグまたはズームすると、同じ相対位置と倍率がすべての列に適用されます。各列はその割合を自分の表示サイズに換算するため、ページの寸法が違っても位置がそろいます。<strong>独立</strong>では列ごとに別々の表示を保ちます。</li><li>連動をオンにすると、最初に見えている列の現在の表示を採用し、残りの列へ適用します。</li><li>設定はブラウザごとに <code>localStorage</code>（<code>manga-memo.original-linked</code>）へ保存され、既定はオンです。2 言語以上を表示しているときだけ意味を持ちます。</li></ul><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>「このページにはまだコマがありません。」</strong> <strong>コマ</strong>（<code>P</code>）に移動して <strong>自動分割</strong> を実行し、戻ってください。</li><li><strong>ドラッグしたら他の言語も動いた。</strong> 重ね表示モードでは <strong>位置合わせ対象</strong> のチップを確認してください。ドラッグされるのは選択中の言語だけです。</li><li><strong>拡大率がずれた。</strong> コマごとのズームとコマごとのオフセットは、ページ全体の値とは別に保存されます。試しに拡大したままなら、現在のコマをリセットしてください。</li><li><strong>スクロール中にペインが動く。</strong> ホイールはペイン内でのみ捕捉されます。通常どおりスクロールするには、ポインターをページの余白へ移動してください。</li><li><strong>スクリーンショットにマスクが写る。</strong> マスクは UI の設定でありエクスポートには含まれませんが、通常の画面キャプチャには写ります。</li><li><strong>チップが灰色になっている。</strong> その言語の画像がこのページにありません。ライブラリの警告か、巻の言語マッピングを確認してください。</li></ul><h2 id="スクリーンショット未掲載" tabindex="-1">スクリーンショット未掲載 <a class="header-anchor" href="#スクリーンショット未掲載" aria-label="Permalink to &quot;スクリーンショット未掲載&quot;">​</a></h2><table tabindex="0"><thead><tr><th>図</th><th>必要な箇所</th></tr></thead><tbody><tr><td>アンカーモードの手順1 / 手順2</td><td>基準点と計算されたオフセット</td></tr></tbody></table><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/guide/panels">コマ分割ワークベンチ</a> — まずコマが必要です。</li><li><a href="/KomaYomi-docs/ja/guide/notes">ノート</a> — 気づいたことを書き留めます。</li><li><a href="/KomaYomi-docs/ja/guide/remote">リモート保存とバックアップ</a> — 画像がローカルにキャッシュされていない場合の動作。</li></ul>',44)])])}const _=e(n,[["render",g]]);export{q as __pageData,_ as default};
